import styled from '@emotion/styled';
import { theme } from 'theme';

import { CHIP_INFO_BACKGROUND } from '../../Chip.constants';

interface StyledChipRootProps {
  $clickable: boolean;
  $disabled: boolean;
  $removable: boolean;
  $selected: boolean;
}

export const StyledChipRoot = styled('div')<StyledChipRootProps>(
  ({ $clickable, $disabled, $removable, $selected }) => ({
    alignItems: 'center',
    borderRadius: '9999px',
    color: theme.colors.interfaceLabelPrimary,
    cursor: $clickable ? 'pointer' : 'default',
    display: 'flex',
    flexDirection: 'row',
    height: '2rem',
    justifyContent: 'center',
    padding: '0 16px',
    transition: 'all 0.2s',
    width: 'max-content',
    ...(!$removable && {
      outlineColor: theme.colors.interfaceSurfaceSecondary,
      outlineStyle: 'solid',
      outlineWidth: '1px',
    }),
    ...($disabled && {
      cursor: 'default',
    }),
    ...(!$disabled &&
      !$removable && {
        backgroundColor: theme.colors.neutral0,
        '&:hover': {
          backgroundColor: CHIP_INFO_BACKGROUND,
          outline: 'none',
        },
        '&:active': {
          backgroundColor: CHIP_INFO_BACKGROUND,
        },
      }),
    ...($selected &&
      !$disabled &&
      !$removable && {
        backgroundColor: CHIP_INFO_BACKGROUND,
        color: theme.colors.interfaceLabelPrimary,
        outline: 'none',
      }),
    ...(!$disabled &&
      $removable && {
        backgroundColor: CHIP_INFO_BACKGROUND,
        color: theme.colors.semanticInfoText,
        outline: 'none',
        '&:hover': {
          backgroundColor: CHIP_INFO_BACKGROUND,
        },
        '&:active': {
          backgroundColor: CHIP_INFO_BACKGROUND,
        },
      }),
    ...($disabled &&
      $removable && {
        backgroundColor: theme.colors.interfaceSurfacePrimary,
      }),
  }),
);
